import pytest

from helpers import compare_gui_row, read_csv

ROWS = read_csv("gpower_gui_vectors.csv")

# SPEC R-18: the G*Power value itself is numerically noisy here; we compute the
# exact answer, so the mismatch is expected and recorded.
KNOWN_DEVIATION = {"V52"}
R18 = ("R-18: G*Power's non-central F is numerically noisy for df2 ~ 1e9; "
       "we do not imitate it (known numerical deviation)")


def _params():
    for row in ROWS:
        vid = row.get("id", "").strip()
        marks = []
        if vid.upper() in KNOWN_DEVIATION:
            marks.append(pytest.mark.xfail(strict=True, reason=R18))
        yield pytest.param(row, id=vid, marks=marks)


@pytest.mark.skipif(not ROWS, reason="oracle/gpower_gui_vectors.csv not found")
@pytest.mark.parametrize("row", list(_params()))
def test_gui_vector(row):
    bad = compare_gui_row(row)
    assert not bad, "; ".join(bad)


@pytest.mark.skipif(not ROWS, reason="oracle/gpower_gui_vectors.csv not found")
def test_gui_no_unexplained_noise_rows():
    """Other huge-df2 vectors (SPEC R-18 'similar') may deviate; list, don't fail."""
    for row in ROWS:
        if row.get("id", "").strip().upper() in KNOWN_DEVIATION:
            continue
        try:
            df2 = float(row.get("gp_df2") or 0)
        except ValueError:
            continue
        if df2 >= 1e8 and compare_gui_row(row):
            pytest.xfail(f"{row['id']}: {R18}")
